<div class="chat-heading"><div><span class="eyebrow"><?= e($conversation['customer_name']) ?></span><h2><?= e($conversation['subject']) ?></h2></div><div class="table-actions"><a href="<?= e(url('/vendedor/mensagens')) ?>">← Conversas</a><?php if($conversation['status']==='open'):?><form method="post" action="<?= e(url('/vendedor/mensagens/'.$conversation['id'].'/encerrar')) ?>"><?= csrf_field() ?><button>Encerrar conversa</button></form><?php endif;?></div></div><section class="chat-panel"><div class="chat-messages"><?php foreach($messages as $message):?><article class="chat-message <?= (int)$message['sender_id']===(int)$authUser['id']?'is-mine':'' ?>"><strong><?= e($message['sender_name']) ?></strong><p><?= nl2br(e($message['body'])) ?></p><time><?= date('d/m/Y H:i',strtotime($message['created_at'])) ?></time></article><?php endforeach;?></div><?php if($conversation['status']==='open'):?><form class="chat-compose" method="post" action="<?= e(url('/vendedor/mensagens/'.$conversation['id'])) ?>"><?= csrf_field() ?><textarea name="body" required maxlength="5000" placeholder="Responder ao cliente..."></textarea><button class="button button--primary">Enviar</button></form><?php else:?><div class="alert">Conversa encerrada.</div><?php endif;?></section>
